// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the wall clock.
func RealClock() Clock { return realClock{} }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	lastFill time.Time // last refill time
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be positive")

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// (bucket capacity), starting full. If clock is nil, the real clock is used.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock()
	}
	return &Limiter{
		rate:     rate,
		burst:    burst,
		tokens:   burst,
		lastFill: clock.Now(),
		clock:    clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
func (l *Limiter) AllowN(n float64) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastFill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastFill = now
	}
	if n < 0 || l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the current number of available tokens (after refilling).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastFill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastFill = now
	}
	return l.tokens
}
